// Встроенный светодиод на Arduino Uno подключен к пину 13
const int ledPin = 13;

void setup() {
  // Инициализируем пин как выход
  pinMode(ledPin, OUTPUT);
}

void loop() {
  digitalWrite(ledPin, HIGH);  // Включаем светодиод (подаем 5В)
  delay(1000);                 // Ждем 1000 миллисекунд (1 секунда)

  digitalWrite(ledPin, LOW);   // Выключаем светодиод (подаем 0В)
  delay(1000);                 // Ждем 1 секунду
}
